```dart
import 'package:flutter/material.dart';

void main() {
  runApp(MyApp());
}

class MyApp extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      home: Scaffold(
        appBar: AppBar(
          title: Text('Ripple Button Example'),
        ),
        body: Center(
          child: MyRippleButton(),
        ),
      ),
    );
  }
}

